using System.Web.Script.Serialization;
using System.Windows;
using System.Windows.Controls;
namespace ClearSpace {
public sealed partial class Controller {
 async Task VerifyRulePacks(string output,Action<bool,string> check){
  var options=new CleanerSettings();int saves=0;UiText.SetLanguage("zh-CN");
  await WithSettings(options,null,root=>{((TabControl)root.FindName("RulesTabs")).SelectedItem=root.FindName("RulesTab");check(root.FindName("RuleProvider")==null&&root.FindName("EnableJson")==null,"Rule management has separate Winapp2 and JSON cards without a source editor switch");check(((Button)root.FindName("RulePacks")).Content.ToString()=="管理 JSON 规则","A single JSON management entry replaces overlapping import destinations");var ini=(CheckBox)root.FindName("EnableWinapp2");ini.IsChecked=false;ini.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));check(!options.Winapp2Enabled&&!options.JsonEnabled&&saves==1,"Winapp2 switches save independently without enabling JSON");var auto=(CheckBox)root.FindName("Automatic");auto.IsChecked=true;auto.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));check(options.AutoWinapp2&&!options.AutoJson,"Each rule source retains its own automatic-update preference");App.Render(Window,Path.Combine(output,"rules-cards.png"));},value=>saves++);
  string directory=Path.Combine(output,"pack-ui-fixture");Directory.CreateDirectory(directory);var store=new RulePackCatalog(Path.Combine(directory,"definitions"));var primary=new RuleStore(Path.Combine(directory,"primary"));store.Import(RulePackTests.Raw(),"example.json");var fixture=Path.Combine(directory,"Cache");Directory.CreateDirectory(fixture);string file=Path.Combine(fixture,"old.log");File.WriteAllText(file,"preview fixture");File.SetLastWriteTimeUtc(file,DateTime.UtcNow.AddDays(-60));var rule=new Rule("library-preview-fixture","Fixture cache","软件缓存","","",new[]{fixture},30,false){ForceBackup=true};
  var entered=new TaskCompletionSource<bool>();using(var gate=new ManualResetEventSlim(false)){
