    check(list.Items.Count==2&&((InstalledRulePack)((ListBoxItem)list.Items[0]).Tag).IsPrimary,"JSON management lists the existing default library and imported files together");check(!((Button)root.FindName("PackRemove")).IsEnabled&&((FrameworkElement)root.FindName("JsonCloud")).Visibility==Visibility.Visible,"The default library can be disabled and updated but cannot be removed");list.SelectedIndex=1;check(((FrameworkElement)root.FindName("JsonCloud")).Visibility==Visibility.Collapsed&&((Button)root.FindName("PackRemove")).IsEnabled,"Imported file actions are independent from default-library online settings");enabled.IsChecked=true;enabled.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));check(store.List().Single().Enabled&&changed==1&&notices==1,"Pack enable switches persist immediately and report success");App.Render(Window,Path.Combine(output,"rule-packs-dark.png"));
