    for(int i=0;i<300&&preview.Content.ToString()!="只读预览";i++)await Task.Delay(10);check(preview.Content.ToString()=="只读预览"&&File.Exists(file)&&list.IsEnabled&&progress.Visibility==Visibility.Collapsed,"Cancelled preview restores controls and keeps its cache file");gate.Set();preview.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));for(int i=0;i<300&&preview.Content.ToString()!="只读预览";i++)await Task.Delay(10);check(details.Text.Contains(file)&&File.Exists(file),"Preview results show paths without deleting files");
    string batch=Path.Combine(directory,"batch.json"),legacy=Path.Combine(directory,"legacy.json"),bad=Path.Combine(directory,"invalid.json");File.WriteAllText(batch,RulePackTests.Raw("ui-batch"));var json=new JavaScriptSerializer();var old=json.Deserialize<ApplicationRulePack>(RulePackTests.Raw());old.Schema=1;old.PackId=null;old.Name=null;old.Rules[0].Conditions=null;File.WriteAllText(legacy,json.Serialize(old));File.WriteAllText(bad,"{invalid");int confirmations=0;RulePackCenter.ImportFilesFixture=()=>new[]{batch,legacy,bad};RulePackCenter.ConfirmImportFixture=text=>{confirmations++;return true;};import.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));for(int i=0;i<300&&!import.IsEnabled;i++)await Task.Delay(10);check(import.IsEnabled&&confirmations==1&&store.List().Count==3&&list.Items.Count==4,"One multi-file selection imports both JSON formats with one confirmation");check(details.Text.Contains("invalid.json")&&details.Text.Contains("失败")&&details.Text.Contains("成功"),"Batch results report invalid and imported files individually");check(store.List().Where(p=>p.FileName=="batch.json"||p.FileName=="legacy.json").All(p=>!p.Enabled),"Batch-imported files remain opt-in while existing enablement is retained");
    list.SelectedIndex=0;enabled.IsChecked=true;enabled.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));check(options.JsonEnabled&&!options.Winapp2Enabled&&store.List().Single(p=>p.FileName=="example.json").Enabled,"Default JSON enablement does not alter Winapp2 or imported-file switches");((TextBox)root.FindName("JsonUpdateUrl")).Text="https://example.test/rules.json";((CheckBox)root.FindName("JsonAutomatic")).IsChecked=true;((Button)root.FindName("JsonSave")).RaiseEvent(new RoutedEventArgs(Button.ClickEvent));check(options.UpdateUrl=="https://example.test/rules.json"&&options.AutoJson&&options.AutoWinapp2,"The default JSON address and automatic checks save independently");
    bool jsonRequest=false;RuleCenter.UpdateFixture=(ini,address,token)=>{jsonRequest=!ini&&address==options.UpdateUrl;return Task.FromResult(0);};((Button)root.FindName("JsonCheck")).RaiseEvent(new RoutedEventArgs(Button.ClickEvent));check(jsonRequest&&import.IsEnabled,"The default-library check uses only its JSON endpoint and restores controls");RuleCenter.UpdateFixture=null;
    var online=(Expander)root.FindName("JsonCloud");online.IsExpanded=true;await Task.Delay(220);check(((TextBlock)root.FindName("JsonCloudHeading")).Foreground==App.Brush("#DFEAF2"),"Expanded JSON online settings use the readable themed heading brush");double previousWidth=Window.Width,previousHeight=Window.Height;Window.Width=1040;Window.Height=740;Window.UpdateLayout();check(((Button)root.FindName("JsonCheck")).ActualWidth>0&&details.ActualHeight>40,"Online JSON settings and rule details fit the compact window together");App.Render(Window,Path.Combine(output,"json-online-small.png"));Window.Width=previousWidth;Window.Height=previousHeight;online.IsExpanded=false;
    list.SelectedIndex=1;UiTheme.Set("light",false);UiText.SetLanguage("en");App.Render(Window,Path.Combine(output,"rule-packs-light-english.png"));check(preview.Content.ToString()=="Read-only preview"&&import.Content.ToString()=="Import JSON (multiple files)","The JSON manager follows English localization and the current theme");BackPage();check(rulePackView==null&&pages.Count==0,"JSON manager back navigation releases its close guard");
   }finally{gate.Set();RulePackCenter.PreviewFixture=null;RulePackCenter.ImportFilesFixture=null;RulePackCenter.ConfirmImportFixture=null;RuleCenter.UpdateFixture=null;UiText.SetLanguage("zh-CN");UiTheme.Set("dark",false);if(rulePackView==null||rulePackView.TryLeave())while(pages.Count>0)BackPage();}
  }
 }
}
